const Redis = require('ioredis');
const redis = new Redis({ host: 'redis', port: 6379, db: 0, connectTimeout: 5000 });

const BATCH_SIZE = 100;

try {
    // Source of truth: connection logs contain IPs for ALL users ever seen (up to 10k entries).
    // Pilot hash keys (intel:pilot_*) expire after 15 min so scanning them is useless for history.
    const logs = await redis.lrange('intel:logs:connections', 0, 9999);

    if (logs.length === 0) return [];

    // Extract unique IPs from log entries
    const uniqueIps = new Set();
    for (const logStr of logs) {
        try {
            const log = JSON.parse(logStr);
            if (log.ip && log.ip !== 'unknown') uniqueIps.add(log.ip);
        } catch(e) {}
    }

    const ipsToCheck = Array.from(uniqueIps);
    if (ipsToCheck.length === 0) return [];

    // Check which IPs are not yet geo-cached
    const cachePipeline = redis.pipeline();
    ipsToCheck.forEach(ip => cachePipeline.get(`intel:geo:${ip}`));
    const cacheResults = await cachePipeline.exec();

    const toFetch = [];
    ipsToCheck.forEach((ip, index) => {
        const [err, result] = cacheResults[index];
        if (!result || result === 'null') {
            // IPv6: colon means public IPv6, fetch it
            if (ip.includes(':')) {
                toFetch.push(ip);
                return;
            }
            // Filter private IPv4 ranges
            const parts = ip.split('.').map(Number);
            if (parts.length === 4) {
                if (parts[0] === 10 || parts[0] === 127 ||
                   (parts[0] === 172 && parts[1] >= 16 && parts[1] <= 31) ||
                   (parts[0] === 192 && parts[1] === 168) ||
                   (parts[0] === 169 && parts[1] === 254)) {
                    return;
                }
                toFetch.push(ip);
            }
        }
    });

    if (toFetch.length === 0) return [];

    // Prepare batch for HTTP node (ip-api.com limit is 100 per request)
    const batch = toFetch.slice(0, BATCH_SIZE);
    const payload = batch.map(query => ({ query, fields: 'status,country,countryCode' }));

    return [{ 
        json: { 
            ips: batch,
            payload: payload
        } 
    }];

} finally {
    if (redis) redis.quit();
}

const Redis = require('ioredis');
const redis = new Redis({ host: 'redis', port: 6379, db: 0, connectTimeout: 5000 });

const GEO_CACHE_TTL = 2592000; // 30 days
const GEO_NULL_TTL = 300;      // 5 minutes

try {
    // Retrieve the IPs we requested from the first node
    const prepareNode = $('Prepare Batch').first();
    if (!prepareNode) return [{ json: { status: 'no_data' } }];

    const ips = prepareNode.json.ips;

    // The HTTP node might return the array of results as a single item's JSON,
    // OR split it into multiple items. 
    // If split (default often), 'items' is the array of results.
    // If not split, items[0].json is the array.

    let results = [];
    if (items.length > 1) {
        results = items.map(i => i.json);
    } else if (Array.isArray(items[0].json)) {
        results = items[0].json;
    } else {
        results = [items[0].json]; // Single result case
    }

    const savePipe = redis.pipeline();
    let successCount = 0;

    ips.forEach((ip, idx) => {
        if (idx >= results.length) return;
        const res = results[idx];
        const key = `intel:geo:${ip}`;

        if (res && res.status === 'success') {
            const data = { country: res.country, code: res.countryCode };
            savePipe.set(key, JSON.stringify(data), 'EX', GEO_CACHE_TTL);
            successCount++;
        } else {
            savePipe.set(key, 'null', 'EX', GEO_NULL_TTL);
        }
    });

    await savePipe.exec();

    return [{ 
        json: { 
            status: 'success', 
            saved: successCount, 
            total: ips.length
        } 
    }];

} finally {
    if (redis) redis.quit();
}
